# Draft: Heart of Ruin (stunning dash engage), Marcella, Cassi/Issac, Prism, Varg.
#   Stellar or a random pick fills any gap.
# Roles:
#  - Heart of Ruin / Varg / Marcella: melee frontline. Buy strength shards.
#    Heart opens fights with its stunning dash.
#  - Cassi/Issac / Prism / others: buy focus shards and pour abilities in.
# Fights: whoever sees enemies sets a shared team target. Every champion opens with any
#   slot where slot_stun > 0 (cast or dash), then damage abilities, attack, attack-reset.
#   We engage only when local_strength favours us; otherwise we kite back.
# Economy: champions claim distinct gem-rich camps, avoiding the monolith all game and
#   golems early. They capture cleared camps, tribute at 40+ gems, and recall when low.

def try_stun(s, t):
    if slot_stun(s) > 0 and ability_ready(s) and distance(position(), unit_position(t)) <= slot_range(s) + 1:
        if slot_is_dash(s):
            dash_towards(s, unit_position(t))
        else:
            cast_at_unit(s, t)

def try_dmg(s, t):
    if (slot_is_damage(s) or slot_is_aoe(s)) and ability_ready(s) and distance(position(), unit_position(t)) <= slot_range(s):
        cast_at_unit(s, t)

