    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 30% health when threatened; recall only when clear
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# ---- combat ----
let foe = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(foe) and not contains( spawn_region(enemy()), unit_position(foe) ):
    # trade check via unit_health: when hurt and the target has much more health left, step out of the trade
    if health() < 0.4 * max_health() and unit_health(foe) > 1.5 * health() and enemies_within(4) >= 1 and can_move():
        move_away_from( unit_position(foe) )
        end_turn()
    # ranged kiting: an adjacent melee enemy gets a step back, then we shoot from range
    if i_am_ranged() and distance(unit_position(foe), position()) <= 1 and can_move():
        move_away_from( unit_position(foe) )
    if role_lead:
        # leader: call the target and open on it
        set_team_target(foe)
        fight(foe)
        end_turn()
    let tf = team_target()
    if exists(tf) and in_reach(tf) and not contains( spawn_region(enemy()), unit_position(tf) ):
        # follower: focus the leader's target
        fight(tf)
        end_turn()
    if not exists(tf):
        set_team_target(foe)
    fight(foe)
    end_turn()

# ---- tribute ----
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
