end_turn()

# PLAN (vision axis: "fog ambush"):
# - Draft stun/burst champions (Heart of Ruin, Ryth, Cassi/Issac, Vesper, Marcella).
# - Fight from fog: when a local fight is unfavourable, do not flee in the open.
#   Slip into the nearest bush (enemy loses vision, chase breaks) and keep shooting
#   if anything is in range.
# - Wards give us vision where it matters:
#   - on the altar while tributing (see interceptors coming);
#   - on capture tiles while standing 5 turns;
#   - on our own tile during fights, so enemies hiding in bushes stay visible.
# - LURKER role (Heart of Ruin, its stun dash cancels channels):
#   - in timed windows, hide in a bush beside the nearest altar and ward that altar;
#   - when an enemy shows up to tribute, stun-dash it, kill it, and take its gems.
# - Everyone else farms rich non-monolith camps with claims. They tribute at 30+ gems,
#   using an unlocked altar.
# - Focus fire through team_target; open fights with stun slots.

def fight(u):
    if ability_ready(0) and slot_stun(0) > 0 and distance(unit_position(u), position()) <= slot_range(0) + 1:
        if slot_is_dash(0):
            dash_towards(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    if ability_ready(1) and slot_stun(1) > 0 and distance(unit_position(u), position()) <= slot_range(1) + 1:
        if slot_is_dash(1):
            dash_towards(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    if ability_ready(0) and slot_is_damage(0) and distance(unit_position(u), position()) <= slot_range(0):
        cast_at_unit(0, u)
    if ability_ready(1) and slot_is_damage(1) and distance(unit_position(u), position()) <= slot_range(1):
        cast_at_unit(1, u)
    if ability_ready(0) and slot_is_aoe(0) and slot_stun(0) == 0 and distance(unit_position(u), position()) <= slot_range(0):
        cast_at_tile(0, unit_position(u))
    if ability_ready(1) and slot_is_aoe(1) and slot_stun(1) == 0 and distance(unit_position(u), position()) <= slot_range(1):
        cast_at_tile(1, unit_position(u))
    if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)) and health() < 0.7 * max_health():
        cast_self(0)
    if ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)) and health() < 0.7 * max_health():
        cast_self(1)
    if distance(unit_position(u), position()) <= 1 or (i_am_ranged() and distance(unit_position(u), position()) <= 3):
        attack(u)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(u)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(u)
    else:
        if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0 and distance(unit_position(u), position()) >= 3:
            dash_towards(0, unit_position(u))
        elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0 and distance(unit_position(u), position()) >= 3:
            dash_towards(1, unit_position(u))
        move_towards(unit_position(u))

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_cassi_issac()):
        pick(champ_cassi_issac())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    else:
        pick(random_champion(pool))
    end_turn()

if not alive():
    if gold() >= 30:
        buy(shard(stat_strength()), floor(gold() / 30))
    end_turn()

if channeling():
    end_turn()

let me = position()
let home = spawn_region(ally())
if contains(home, me) and gold() >= 30:
    buy(shard(stat_strength()), floor(gold() / 30))

let hpf = health() / max_health()
let foes = enemies_visible()
let nfoe = count(foes)

# --- low health: hide in fog, then go home ---
if hpf < 0.3:
    if contains(home, me):
        end_turn()
    if nfoe == 0:
        recall()
    else:
        let cover = closest(filter(bushes(), within(2, me)))
        if exists(cover) and not contains(bushes(), me):
            move_towards(cover)
        else:
            move_towards(closest(home))
    end_turn()

# heal up fully when already home
if contains(home, me) and hpf < 0.85 and nfoe == 0:
    end_turn()

# --- combat ---
if nfoe > 0:
    let ls = local_strength(6)
    let w = weakest(foes)
    if ls < 0.7 and hpf < 0.65:
        # fight from fog: break vision via a bush, keep shooting if possible
        let inr = first(filter(foes, in_attack_range()))
        if exists(inr) and can_attack():
            attack(inr)
        let cover = closest(filter(bushes(), within(3, me)))
        if exists(cover) and not contains(bushes(), me):
            move_towards(cover)
        elif not contains(bushes(), me):
            move_away_from(unit_position(nearest(foes)))
        end_turn()
    place_ward(me)
    let tt = team_target()
    if exists(tt) and distance(unit_position(tt), me) <= 6:
        fight(tt)
    else:
        set_team_target(w)
        fight(w)
    end_turn()

# --- tribute with an altar ward ---
let alt = closest(minus(altars(), locked_altars()))
if exists(alt) and (gems() >= 30 or (gems() > 0 and round_number() > 1850)):
    if distance(alt, me) <= 1:
        place_ward(alt)
        tribute(alt)
    else:
        move_towards(alt)
    end_turn()

# --- lurker: altar ambush from a bush ---
let phase = round_number() / 200 - floor(round_number() / 200)
if i_am(champ_heart_of_ruin()) and round_number() > 250 and phase < 0.35 and exists(alt):
    let lurk = closest(filter(bushes(), within(3, alt)))
    if exists(lurk):
        if distance(lurk, me) == 0:
            place_ward(alt)
            end_turn()
        move_towards(lurk)
        end_turn()

# --- capture cleared camps (ward the tile) ---
let cap = closest(capturable_spawns())
if exists(cap) and distance(cap, me) <= 8:
    if distance(cap, me) == 0:
        place_ward(me)
        end_turn()
    move_towards(cap)
    end_turn()

# --- farm rich non-monolith camps ---
keep mono = group_tiles(monolith_tiles())
keep safe = minus(rich_spawns(4), mono)
let c = nearest(filter(camps_visible(), in_attack_range()))
if exists(c) and not contains(mono, unit_position(c)):
    attack(c)
    end_turn()
let goal = closest(minus(minus(safe, claimed_by_allies()), respawning_visible_spawns()))
if exists(goal):
    claim(goal)
    move_towards(goal)
    end_turn()
let goal2 = closest(minus(safe, respawning_visible_spawns()))
if exists(goal2):
    move_towards(goal2)
    end_turn()
if exists(alt):
    move_towards(alt)

# items/stats line: each champion buys the stat its role needs, on top of the v1 team-target combat and economy.
# Plan (items and stats axis):
# 1. Focus carries (Vesper Vale, Marcella, Stellar) buy focus shards, half as the Power emblem family, so ability damage scales.
# 2. Durable front-liners (Ren, Varg, Heart of Ruin) buy health shards, half as the Durability emblem, to survive the trade.
# 3. Everyone else keeps the v1 mix: treasure strength emblem, jungle health, then strength and health shards.
# 4. Combat, recall, tribute and camp logic are unchanged from v1 (team target, attack reset, openers).
# 5. Fuel-gated vision wards by Heart of Ruin and Vesper Vale stay as before.

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
# monolith groups never change: one group_tiles() per game (fuel; bot-session check)
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    if i_am(champ_vesper_vale()) or i_am(champ_marcella()) or i_am(champ_stellar()):
        # focus carries: ability damage scales with focus, half the buy as the Power emblem family
        buy( shard_of(family_power(), stat_focus()), floor( shards_bought / 2 ) )
        buy( shard(stat_focus()), shards_bought - floor( shards_bought / 2 ) )
    elif i_am(champ_ren()) or i_am(champ_varg()) or i_am(champ_heart_of_ruin()):
        # durable front-liners: health shards, half as the Durability emblem family
        buy( shard_of(family_durability(), stat_health()), floor( shards_bought / 2 ) )
        buy( shard(stat_health()), shards_bought - floor( shards_bought / 2 ) )
    else:
        let treasure_n = floor( shards_bought / 2 )
        let rest_after_treasure = shards_bought - treasure_n
        let jungle_n = floor( rest_after_treasure / 2 )
        let rest_after_jungle = rest_after_treasure - jungle_n
        let strength_shards = floor( rest_after_jungle / 2 )
        buy( shard_of(family_treasure(), stat_strength()), treasure_n )
        buy( shard_of(family_jungle(), stat_health()), jungle_n )
        buy( shard(stat_strength()), strength_shards )
        buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 30% health; recall only when no enemy champion is within 8
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate (a cross-map retreat is several host searches)
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# team focus: is the shared team target within our own attack range?
let tt_d = distance( position(), unit_position( team_target() ) )
let tt_ok = (i_am_ranged() and tt_d <= 3) or ((not i_am_ranged()) and tt_d <= 1)
if tt_ok and exists(team_target()) and not contains( spawn_region(enemy()), unit_position(team_target()) ):
    cast_on(0, team_target())
    cast_on(1, team_target())
    attack(team_target())
    # attack reset: a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(team_target())
    end_turn()

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
# an enemy on its own spawn is healed every turn: do not fight it there
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    set_team_target(enemy)
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach; else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# nothing tributed by round 800: go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group (elk 60, wolf 20 per camp); fuel guard on the extra walk
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of an uncleared group, walk to the nearest living camp (not a monolith or golem)
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# dash toward a far camp goal (fuel guard: skip on a near-cap turn)
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)

# VISION: the front-liners (Heart of Ruin, Vesper Vale) ward a bush within 2 tiles on the way to a goal,
# only when no enemy champion is within 8 and we are not in danger. The bush also hides the warder.
if (i_am(champ_heart_of_ruin()) or i_am(champ_vesper_vale())) and fuel_remaining() > 50000:
    if enemies_within(8) == 0 and not in_danger():
        let ward_bush = first( filter( bushes(), within(2, position()) ) )
        if exists(ward_bush):
            place_ward(ward_bush)

move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# PLAN (combat-micro champion):
# - Draft the meta five (Vesper Vale, Heart of Ruin, Marcella, Vendetta, Ryth).
# - Every turn, think as one champion:
#   1. Dead or channeling: shop or wait.
#   2. Enemy within ENGAGE_R: retreat only when badly hurt or outnumbered.
#      Otherwise fight the team target (focus fire, set by the first ally who sees one)
#      or the nearest enemy, in this order:
#        opener (stun dash or damage ability in reach, shield),
#        close distance only if out of reach (ranged kites away when hurt and adjacent),
#        basic attack, then self-cast any reset and attack again.
#      Always act when an enemy is near: never idle while being hit.
#   3. Carrying gems with an enemy within 8: tribute at once. With no enemy near,
#      bank a big bag (BAG). Prefer altars away from monoliths, but never drop
#      locked altars entirely.
#   4. Recall when low and not in danger; heal on spawn.
#   5. Farm: capture cleared camps, hit visible non-monolith camps (abilities too),
#      and walk to a rich gem group when it is only a few tiles farther than the nearest camp.

def toaltar(a):
    if distance(position(), a) <= 1:
        tribute(a)
    else:
        move_towards(a)

def opener(t, s):
    if ability_ready(s):
        if slot_is_dash(s):
            if distance(position(), unit_position(t)) <= slot_range(s) + 1 and distance(position(), unit_position(t)) > 1:
                dash_towards(s, unit_position(t))
        elif slot_is_shield(s):
            if distance(position(), unit_position(t)) <= 3:
                cast_self(s)
        elif slot_is_heal(s):
            if health() < 0.75 * max_health():
                cast_self(s)
        elif slot_is_reset(s):
            if not can_attack():
                cast_self(s)
        elif distance(position(), unit_position(t)) <= slot_range(s) + slot_radius(s):
            cast_at_unit(s, t)

def hit(t):
    if can_attack():
        if distance(position(), unit_position(t)) <= 1:
            attack(t)
        elif i_am_ranged() and distance(position(), unit_position(t)) <= 3:
            attack(t)

def approach(t):
    if can_move():
        if i_am_ranged():
            if distance(position(), unit_position(t)) <= 1 and health() < 0.5 * max_health():
                move_away_from(unit_position(t))
            elif distance(position(), unit_position(t)) > 3:
                move_towards(unit_position(t))
        elif distance(position(), unit_position(t)) > 1:
            move_towards(unit_position(t))

def fight(t):
    opener(t, 0)
    opener(t, 1)
    approach(t)
    hit(t)
    opener(t, 0)
    opener(t, 1)
    hit(t)

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    else:
        pick(random_champion(pool))
    end_turn()

if not alive():
    if gold() >= 30:
        if round_number() < 300:
            buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
        else:
            buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))
    end_turn()

if channeling():
    end_turn()

keep ENGAGE_R = 6
keep BAG = 40
keep RETREAT_HP = 0.3
keep OUTNUM_HP = 0.55
keep RECALL_HP = 0.4
keep RICH_SLACK = 6

keep mono = monolith_tiles()
keep monozone = ring(mono, 6)
keep monoclose = ring(mono, 3)
keep monogroup = group_tiles(mono)
keep home = spawn_region(ally())
keep rich = minus(rich_spawns(15), monogroup)
keep camps0 = minus(camp_spawn_tiles(), monogroup)
keep safealt = minus(altars(), monozone)

let me = position()
let hp = health() / max_health()
let gm = gems()
let onspawn = contains(home, me)

if onspawn and gold() >= 30:
    if round_number() < 300:
        buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
    else:
        buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

let foes = enemies_visible()
let near = nearest(foes)
let dn = distance(me, unit_position(near))
let alt = closest(safealt)

if exists(near) and dn <= ENGAGE_R:
    let tt = team_target()
    let outnum = enemies_within(6) > allies_within(6) + 1
    if (not onspawn) and (hp < RETREAT_HP or (hp < OUTNUM_HP and outnum)):
        move_away_from(unit_position(near))
        if not in_danger():
            recall()
        end_turn()
    if gm >= 10 and exists(alt) and distance(me, alt) <= 1 and dn >= 4:
        tribute(alt)
        end_turn()
    if exists(tt) and unit_health_frac(tt) > 0 and distance(me, unit_position(tt)) <= ENGAGE_R + 1:
        fight(tt)
    else:
        set_team_target(near)
        fight(near)
    end_turn()

let ew8 = enemies_within(8)
if (gm > 0 and ew8 > 0) or gm >= BAG or (gm > 0 and round_number() > 1950):
    if exists(alt):
        toaltar(alt)
    else:
        toaltar(closest(altars()))
    end_turn()

if hp < RECALL_HP:
    if onspawn:
        end_turn()
    if in_danger():
        move_towards(closest(home))
    else:
        recall()
    end_turn()

if onspawn and hp < 0.9:
    end_turn()

let caps = capturable_spawns()
if count(caps) > 0:
    move_towards(closest(caps))
    end_turn()

let cmp = nearest(camps_visible())
if exists(cmp) and (not contains(monoclose, unit_position(cmp))) and distance(me, unit_position(cmp)) <= 5:
    if hp > 0.5:
        if ability_ready(0) and slot_is_damage(0):
            opener(cmp, 0)
        if ability_ready(1) and slot_is_damage(1):
            opener(cmp, 1)
    approach(cmp)
    hit(cmp)
    end_turn()

let resp = respawning_visible_spawns()
let g1 = closest(minus(camps0, resp))
let g2 = closest(minus(rich, resp))
if exists(g2) and distance(me, g2) <= distance(me, g1) + RICH_SLACK:
    claim(g2)
    move_towards(g2)
elif exists(g1):
    claim(g1)
    move_towards(g1)
else:
    move_towards(closest(camps0))

# PLAN: per-champion roles on top of v1.
#  - Leaders (Vendetta, Vesper Vale): front-line. They pick and name the fight target, act first (high priority).
#  - Hunter (Tavi): chases the team target with dashes when healthy, so the leaders' target gets pressure.
#  - Farmers (Ryth, Ren, others): follow the leaders' target and claim distinct gem camps for the economy.
#  - Leaders never claim camps, so the farmers spread out and the leaders stay near the fight.
# Economy, tribute, recall and shopping are shared, as in v1.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

def in_reach(u):
    return distance(unit_position(u), position()) <= 1 or (i_am_ranged() and distance(unit_position(u), position()) <= 3)

# full engagement on one unit: abilities, basic, reset, basic
def fight(u):
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif not slot_is_dash(0) and not slot_is_reset(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif not slot_is_dash(1) and not slot_is_reset(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
keep role_lead = i_am(champ_vendetta()) or i_am(champ_vesper_vale())
keep role_hunt = i_am(champ_tavi())
keep role_farm = not role_lead and not role_hunt

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

# turn order by role: leaders first, hunter next, farmers last
if role_lead:
    set_priority( 60 + random_int(40) )
elif role_hunt:
    set_priority( 30 + random_int(20) )
else:
    set_priority( 1 + random_int(25) )

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# ---- fighting roles ----
let target_e = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(target_e) and not contains( spawn_region(enemy()), unit_position(target_e) ):
    if role_lead:
        # leader: call the target, then fight it
        set_team_target(target_e)
        fight(target_e)
        end_turn()
    let tf = team_target()
    if exists(tf) and in_reach(tf) and not contains( spawn_region(enemy()), unit_position(tf) ):
        # hunter and farmers: focus the team's target
        fight(tf)
        end_turn()
    if not exists(tf):
        set_team_target(target_e)
    fight(target_e)
    end_turn()

# hunter: when healthy, close distance on the team target with dashes
let tg = team_target()
if role_hunt and exists(tg) and health() > 0.6 * max_health() and fuel_remaining() > 60000 and not contains( spawn_region(enemy()), unit_position(tg) ):
    dash_to(0, unit_position(tg))
    dash_to(1, unit_position(tg))
    move_towards( unit_position(tg) )
    end_turn()

# ---- tribute ----
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# ---- camps in reach ----
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# ---- economy: farmers claim camps; leaders stay mobile and do not claim ----
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if role_farm and exists(goal):
    claim(goal)
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
end_turn()

# tune-team-v1 with per-champion stat buying: Heart of Ruin buys health, Vesper Vale keeps strength,
# other champions split the leftover shards between strength and focus.
# Plan:
# 1. Gem carriers raise byte 7 (1 while carrying gems) so allies know a bag is moving.
# 2. A champion with no gems that sees the flag and a rich ally nearby escorts that carrier
#    (move toward the richest visible ally) instead of starting a new camp; it stops when no enemy is within 8.
# 3. Whoever hits an enemy in reach names it team_target(); allies with that target in reach focus it first.
# 4. Heart of Ruin is the designated escort (roles via i_am), other champions escort too when the flag is up.
# 5. Everything else (draft, tribute, safe recall, camps, teleport) is kept from the parent policy.

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
# monolith groups never change: one group_tiles() per game (fuel; bot-session check)
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

# team signal (byte 7): a gem carrier raises the flag so escorts know a bag is moving
if gems() > 0:
    write_shared(7, 1)
else:
    write_shared(7, 0)

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    # per-champion leftover stats (items and stats axis)
    if i_am(champ_heart_of_ruin()):
        # designated escort/tank: durability for the shield-and-dash fights
        buy( shard(stat_health()), rest_after_jungle )
    elif i_am(champ_vesper_vale()):
        # Power Strength carry
        buy( shard(stat_strength()), rest_after_jungle )
    else:
        # everyone else: split leftover between strength and focus (ability scaling)
        let strength_shards = floor( rest_after_jungle / 2 )
        buy( shard(stat_strength()), strength_shards )
        buy( shard(stat_focus()), rest_after_jungle - strength_shards )
    # teleport crystal (10 gold): bought after the shards with whatever gold is left
    if not has_teleport() and gold() >= 10:
        buy_teleport()
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 20% health normally, but at 50% when carrying gems
# safe recall (tune line): never start a recall with an enemy champion within 8; retreat first, recall when clear
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate (bot session: a cross-map retreat is three ~21k host searches)
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# team focus (coordination): if the team has named a target and it is in our reach, hit it first
let tgt = team_target()
if exists(tgt):
    if distance(unit_position(tgt), position()) <= 1 or (i_am_ranged() and distance(unit_position(tgt), position()) <= 3):
        cast_on(0, tgt)
        cast_on(1, tgt)
        attack(tgt)
        end_turn()

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends (00reverse-spiral)
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # name it for the team so allies converge on the same target
    set_team_target(enemy)
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    # attack reset: a second basic attack after the first (it does nothing before one)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        # teleport crystal: jump 2-3 tiles straight onto the altar ring (ignores walls and terrain)
        if has_teleport() and not channeling() and distance(position(), target) >= 2 and distance(position(), target) <= 3:
            teleport_to(target)
            end_turn()
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp (01boss-battle: holes and a monolith): fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    # attack reset on camps too (tune line): a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# escort (coordination): an empty-handed champion walks to a rich ally while the carrier flag is up
# and no enemy is within 8; Heart of Ruin escorts first (designated guard), others when idle
let rich = richest( allies_visible() )
if gems() == 0 and read_shared(7) == 1 and exists(rich) and unit_gems(rich) >= 10 and enemies_within(8) == 0:
    if distance(position(), unit_position(rich)) > 1:
        move_towards( unit_position(rich) )
        end_turn()

# nothing tributed by round 300 (00contest: only monoliths carry gems): go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group (tune line, 01starvation): elk 60, wolf 20 per camp
# fuel guard: the bank walk is a second distance query this turn
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group that is not cleared yet, the closest goal is our own tile: walk to the
# nearest living camp instead (not a monolith or golem), so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# tunable: dash toward a camp goal only when it is farther than this
# fuel guard (tune line): skip the optional dash on a near-cap turn
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# ABILITY axis plan (one champion, turn by turn):
# 1. Opener: when healthy and an enemy is 2 to slot_range+1 tiles away, dash-stun it (slot_stun > 0),
#    else cast a stun at it, so the first hit lands with the enemy stunned.
# 2. Heal: an injured visible ally in range gets a heal (slot_is_heal) before we cast anything else.
# 3. AoE: an area ability (slot_is_aoe with slot_radius > 0) is cast at the target tile, not the unit.
# 4. Attack reset: basic, reset self-cast, basic (unchanged from tune-v18g).
# 5. Shield/heal on self stay ability-type aware; dashes stay for escape and travel.
# VISION axis (this version): when walking to a camp goal with no enemy champion near, drop a ward
# on a bush within 2 tiles. Bushes block enemy sight, so the ward sits in cover and gives us vision
# over the route to the camp without being seen from the fog.

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif slot_is_aoe(slot) and slot_radius(slot) > 0:
            cast_at_tile(slot, unit_position(u))
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

