# fuel guard (tune line): skip the optional dash on a near-cap turn
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)

# VISION (ward axis): with no enemy champion within 8, drop a ward on a bush within reach
# (2 tiles). Bush cover hides the ward and its sight lines from the enemy, and the fuel gate keeps
# this optional step off heavy turns.
let ward_spot = first( filter( bushes(), within(2, position()) ) )
if exists(ward_spot) and enemies_within(8) == 0 and fuel_remaining() > 50000:
    place_ward(ward_spot)

move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
