# PLAN (vision axis: "fog ambush"):
# - Draft stun/burst champions (Heart of Ruin, Ryth, Cassi/Issac, Vesper, Marcella).
# - Fight from fog: when a local fight is unfavourable, do not flee in the open.
#   Slip into the nearest bush (enemy loses vision, chase breaks) and keep shooting
#   if anything is in range. While hiding in a bush, ward our own tile so enemies
#   lurking in the surrounding bushes stay visible to us and we can keep trading.
# - Wards give us vision where it matters:
#   - on the altar while tributing (see interceptors coming);
#   - on capture tiles while standing 5 turns;
#   - on our own tile during fights, so enemies hiding in bushes stay visible.
# - LURKER role (Heart of Ruin, its stun dash cancels channels):
#   - in timed windows, hide in a bush beside the nearest altar and ward that altar;
#   - when an enemy shows up to tribute, stun-dash it, kill it, and take its gems.
# - Everyone else farms rich non-monolith camps with claims. They tribute at 30+ gems,
#   using an unlocked altar.
# - Focus fire through team_target; open fights with stun slots.

def fight(u):
    if ability_ready(0) and slot_stun(0) > 0 and distance(unit_position(u), position()) <= slot_range(0) + 1:
        if slot_is_dash(0):
            dash_towards(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    if ability_ready(1) and slot_stun(1) > 0 and distance(unit_position(u), position()) <= slot_range(1) + 1:
        if slot_is_dash(1):
            dash_towards(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    if ability_ready(0) and slot_is_damage(0) and distance(unit_position(u), position()) <= slot_range(0):
        cast_at_unit(0, u)
    if ability_ready(1) and slot_is_damage(1) and distance(unit_position(u), position()) <= slot_range(1):
        cast_at_unit(1, u)
    if ability_ready(0) and slot_is_aoe(0) and slot_stun(0) == 0 and distance(unit_position(u), position()) <= slot_range(0):
        cast_at_tile(0, unit_position(u))
    if ability_ready(1) and slot_is_aoe(1) and slot_stun(1) == 0 and distance(unit_position(u), position()) <= slot_range(1):
        cast_at_tile(1, unit_position(u))
    if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)) and health() < 0.7 * max_health():
        cast_self(0)
    if ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)) and health() < 0.7 * max_health():
        cast_self(1)
    if distance(unit_position(u), position()) <= 1 or (i_am_ranged() and distance(unit_position(u), position()) <= 3):
        attack(u)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(u)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(u)
    else:
        if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0 and distance(unit_position(u), position()) >= 3:
            dash_towards(0, unit_position(u))
        elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0 and distance(unit_position(u), position()) >= 3:
            dash_towards(1, unit_position(u))
        move_towards(unit_position(u))

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_cassi_issac()):
        pick(champ_cassi_issac())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    else:
        pick(random_champion(pool))
    end_turn()

if not alive():
    if gold() >= 30:
        buy(shard(stat_strength()), floor(gold() / 30))
    end_turn()

if channeling():
    end_turn()

let me = position()
let home = spawn_region(ally())
if contains(home, me) and gold() >= 30:
    buy(shard(stat_strength()), floor(gold() / 30))

let hpf = health() / max_health()
let foes = enemies_visible()
let nfoe = count(foes)

# --- low health: hide in fog, then go home ---
if hpf < 0.3:
    if contains(home, me):
        end_turn()
    if nfoe == 0:
        recall()
    else:
        let cover = closest(filter(bushes(), within(2, me)))
        if exists(cover) and not contains(bushes(), me):
            move_towards(cover)
        else:
            move_towards(closest(home))
    end_turn()

# heal up fully when already home
if contains(home, me) and hpf < 0.85 and nfoe == 0:
    end_turn()

# --- combat ---
if nfoe > 0:
    let ls = local_strength(6)
    let w = weakest(foes)
    if ls < 0.7 and hpf < 0.65:
        # fight from fog: break vision via a bush, keep shooting if possible
        let inr = first(filter(foes, in_attack_range()))
        if exists(inr) and can_attack():
            attack(inr)
        # hidden in a bush: ward our tile so lurkers around us stay visible
        if contains(bushes(), me):
            place_ward(me)
        let cover = closest(filter(bushes(), within(3, me)))
        if exists(cover) and not contains(bushes(), me):
            move_towards(cover)
        elif not contains(bushes(), me):
            move_away_from(unit_position(nearest(foes)))
        end_turn()
    place_ward(me)
    let tt = team_target()
    if exists(tt) and distance(unit_position(tt), me) <= 6:
        fight(tt)
    else:
        set_team_target(w)
        fight(w)
    end_turn()

# --- tribute with an altar ward ---
let alt = closest(minus(altars(), locked_altars()))
if exists(alt) and (gems() >= 30 or (gems() > 0 and round_number() > 1850)):
    if distance(alt, me) <= 1:
        place_ward(alt)
        tribute(alt)
    else:
        move_towards(alt)
    end_turn()

# --- lurker: altar ambush from a bush ---
let phase = round_number() / 200 - floor(round_number() / 200)
if i_am(champ_heart_of_ruin()) and round_number() > 250 and phase < 0.35 and exists(alt):
    let lurk = closest(filter(bushes(), within(3, alt)))
    if exists(lurk):
        if distance(lurk, me) == 0:
            place_ward(alt)
            end_turn()
        move_towards(lurk)
        end_turn()

# --- capture cleared camps (ward the tile) ---
let cap = closest(capturable_spawns())
if exists(cap) and distance(cap, me) <= 8:
    if distance(cap, me) == 0:
        place_ward(me)
        end_turn()
    move_towards(cap)
    end_turn()

# --- farm rich non-monolith camps ---
keep mono = group_tiles(monolith_tiles())
keep safe = minus(rich_spawns(4), mono)
let c = nearest(filter(camps_visible(), in_attack_range()))
if exists(c) and not contains(mono, unit_position(c)):
    attack(c)
    end_turn()
let goal = closest(minus(minus(safe, claimed_by_allies()), respawning_visible_spawns()))
if exists(goal):
    claim(goal)
    move_towards(goal)
    end_turn()
let goal2 = closest(minus(safe, respawning_visible_spawns()))
if exists(goal2):
    move_towards(goal2)
    end_turn()
if exists(alt):
    move_towards(alt)

# PLAN (macro route & timing, single-champion view):
# 1. Draft the meta five (Vesper Vale, Heart of Ruin, Marcella, Vendetta, Ryth).
# 2. Every turn: dead -> shop.
#    On spawn -> shop and heal to ~95% unless enemies are close.
# 3. Fights (enemy within 6). Pick the target with unit_health:
#    - an enemy we can finish in ~2 hits first,
#    - else the team target,
#    - else the nearest enemy.
#    Fight order: stun opener, basic > reset > basic, damage casts, shield.
#    Ranged champions kite away from an adjacent enemy unless it is nearly dead.
#    Retreat at low HP or when badly outnumbered; never recall in danger.
# 4. Macro timing:
#    - capture cleared groups at once;
#    - bank when the bag reaches 10 + round/60 (grows over the game),
#      or everything late; prefer altars away from monoliths;
#    - after round 1100, healthy low-bag champions claim the monolith but only
#      engage once 2 other allies claim it AND 2 allies stand within 7;
#    - else farm: a rich group (>=15 gems) if it is at most 5 tiles farther
#      than the nearest free camp, skipping monolith groups and respawning camps.

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    else:
        pick(random_champion(pool))
    end_turn()

def shop():
    if gold() >= 30:
        if round_number() < 350:
            buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
        else:
            buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

def fight(t):
    if ability_ready(1) and slot_stun(1) > 0 and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    if ability_ready(0) and slot_stun(0) > 0 and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        else:
            cast_at_unit(0, t)
