# PLAN (mobility axis):
# - Buy a teleport crystal on spawn before shards (10 gold). It is a 3-tile hop that ignores terrain.
# - Teleport-hop to an altar apron when carrying 30+ gems and the altar is 3-6 tiles away, skipping walls.
# - Dashes: stun-dash to open fights and non-stun dash to close 3+ tiles. Guard every dash with fuel.
# - Escape: at low health with an enemy within 2, dash toward home. Teleport home if within 3 tiles.
# - Recall timing: recall at low health only when no foe is visible, then heal at spawn and rejoin.

def fight(u):
    if fuel_remaining() > 30000 and ability_ready(0) and slot_stun(0) > 0 and distance(unit_position(u), position()) <= slot_range(0) + 1:
        if slot_is_dash(0):
            dash_towards(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    if fuel_remaining() > 30000 and ability_ready(1) and slot_stun(1) > 0 and distance(unit_position(u), position()) <= slot_range(1) + 1:
        if slot_is_dash(1):
            dash_towards(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    if ability_ready(0) and slot_is_damage(0) and distance(unit_position(u), position()) <= slot_range(0):
        cast_at_unit(0, u)
    if ability_ready(1) and slot_is_damage(1) and distance(unit_position(u), position()) <= slot_range(1):
