# PLAN (ability-centred team, built from scratch)
# Draft: Heart of Ruin (stun dash diver), Vesper Vale (reset carry), Ryth (AoE stun),
#   Marcella (burst), Vendetta (dash + reset), then random.
# Every champion fights the same way, driven by its ability slots:
#   1. Stun opener first: slot_stun > 0 and target within slot_range + slot_radius.
#      Dash stuns use dash_towards, area stuns use cast_at_tile on the target's tile,
#      single-target stuns use cast_at_unit.
#   2. Shield on cooldown once an enemy is close. Heal the weakest ally if it is low, else self.
#   3. Melee closes the gap (a non-stun dash from 3+ tiles), then basic attacks.
#      Ranged champions kite away from an adjacent enemy when hurt, else attack from range.
#   4. Reset: self-cast right AFTER a landed basic, then attack again.
#   5. Leftover damage/AoE (no stun) is spent on the same target (AoE at its tile).
# Focus fire: team_target if it is visible and close, else the nearest enemy (set as the target).
# Retreat only when low or clearly outnumbered: stun the chaser, shield, dash/step away.
# Macro: capture cleared camps, farm the nearest camp but prefer a rich group a few tiles
#   farther, never touch monoliths, tribute bags of 30 at altars away from monoliths.
#   Abilities are also used on camps to clear faster.
# Shop: Treasure shards early, then Bruiser Strength.

def dt(t):
    return distance(position(), unit_position(t))

def reach(s):
    return slot_range(s) + slot_radius(s)

def go_tribute(a):
    if distance(position(), a) <= 1:
        tribute(a)
    else:
        move_towards(a)
    end_turn()

def fight(t):
    if i_am_ranged() and dt(t) <= 1 and hf < KITE_HF and can_move():
        move_away_from(unit_position(t))
    if ability_ready(0) and slot_stun(0) > 0 and dt(t) <= reach(0):
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        elif slot_radius(0) > 0:
            cast_at_tile(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    if ability_ready(1) and slot_stun(1) > 0 and dt(t) <= reach(1):
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        elif slot_radius(1) > 0:
            cast_at_tile(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    if ability_ready(0) and slot_is_shield(0) and dt(t) <= 3:
        cast_self(0)
    if ability_ready(1) and slot_is_shield(1) and dt(t) <= 3:
        cast_self(1)
    if ability_ready(0) and slot_is_heal(0):
        if exists(mate) and unit_health_frac(mate) < 0.6 and dt(mate) <= slot_range(0):
            cast_at_unit(0, mate)
        elif hf < 0.7:
            cast_self(0)
    if ability_ready(1) and slot_is_heal(1):
        if exists(mate) and unit_health_frac(mate) < 0.6 and dt(mate) <= slot_range(1):
            cast_at_unit(1, mate)
        elif hf < 0.7:
            cast_self(1)
    if not i_am_ranged() and dt(t) > 1 and can_move():
        if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0 and dt(t) >= 3:
            dash_towards(0, unit_position(t))
        elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0 and dt(t) >= 3:
            dash_towards(1, unit_position(t))
        else:
            move_towards(unit_position(t))
    if i_am_ranged() and dt(t) > 3 and can_move():
        move_towards(unit_position(t))
    if can_attack():
        attack(t)
    if not can_attack() and (dt(t) <= 1 or (i_am_ranged() and dt(t) <= 3)):
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
