        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    # attack reset on camps too (tune line): a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# nothing tributed by round 300 (00contest: only monoliths carry gems): go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()

# monolith commit (late game, team macro): after round 1000 a healthy champion joins a monolith that an
# ally already claims (2+ attackers); after round 1200 the first healthy champion claims the closest one.
# Not in_danger here: the retreat block above has already handled threatened champions.
if round_number() > 1000 and health() > 0.7 * max_health():
    let mono_goal = closest( monolith_tiles() )
    if exists(mono_goal):
        if claim_count(mono_goal) >= 1:
            move_towards(mono_goal)
            end_turn()
        if round_number() > 1200 and claim_count(mono_goal) == 0:
            claim(mono_goal)
            move_towards(mono_goal)
            end_turn()

let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group (tune line, 01starvation): elk 60, wolf 20 per camp
# fuel guard: the bank walk is a second distance query this turn
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group that is not cleared yet, the closest goal is our own tile: walk to the
# nearest living camp instead (not a monolith or golem), so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# tunable: dash toward a camp goal only when it is farther than this
# fuel guard (tune line): skip the optional dash on a near-cap turn
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)

# VISION (ward axis): with no enemy champion within 8, drop a ward on a bush within reach
# (2 tiles). Bush cover hides the ward and its sight lines from the enemy, and the fuel gate keeps
# this optional step off heavy turns.
let ward_spot = first( filter( bushes(), within(2, position()) ) )
if exists(ward_spot) and enemies_within(8) == 0 and fuel_remaining() > 50000:
    place_ward(ward_spot)

move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# PLAN: per-champion roles that move as a pack early and spread out later.
#  Draft order: Heart of Ruin (stun dash), Ryth (stun AoE), Vesper Vale, Vendetta,
#  Marcella, Cassi/Issac, Varg, Willow, else random.
#  Roles:
#   HUNTER (Heart of Ruin, Vendetta, Varg): strength shards, farms elks/wolves,
#     golems after round 300. Engages enemies at lower odds and sets the team target.
#   GUARD (Ryth, Willow, Marcella, Tavi): health shards, farms only camps near our
#     altar and holds the altar area. Fights when the local fight is even.
#   FARMER (everyone else): strength shards, farms gem clusters and wolves.
#     Only fights with a clear edge.
#  Before round 150 the enemy arrives together, so we group too: the first
#  champion to choose claims a camp and everyone else follows the closest claim.
#  After round 150, each role takes unclaimed camps, so the team spreads out.
#  Everyone tributes at 30 gems, earlier when hurt, and anything carried late.
#  Retreat below 35% health. Never hit monoliths; non-hunters avoid golems
#  unless those camps are already awake.

def fight(u, ls, h, g):
    if ls >= 1.2 or (h and ls >= 0.8) or (g and ls >= 1.0) or unit_health_frac(u) < 0.25:
        set_team_target(u)
        if ability_ready(0) and slot_is_shield(0):
            cast_self(0)
        if ability_ready(1) and slot_is_shield(1):
            cast_self(1)
        if ability_ready(0) and (slot_stun(0) > 0 or slot_is_damage(0) or slot_is_aoe(0)) and not slot_is_dash(0) and distance(position(), unit_position(u)) <= slot_range(0):
            cast_at_unit(0, u)
        if ability_ready(1) and (slot_stun(1) > 0 or slot_is_damage(1) or slot_is_aoe(1)) and not slot_is_dash(1) and distance(position(), unit_position(u)) <= slot_range(1):
            cast_at_unit(1, u)
        if ability_ready(0) and slot_is_dash(0) and distance(position(), unit_position(u)) >= 2 and distance(position(), unit_position(u)) <= 4:
            dash_towards(0, unit_position(u))
        if ability_ready(1) and slot_is_dash(1) and distance(position(), unit_position(u)) >= 2 and distance(position(), unit_position(u)) <= 4:
            dash_towards(1, unit_position(u))
        if can_attack() and (distance(position(), unit_position(u)) <= 1 or (i_am_ranged() and distance(position(), unit_position(u)) <= 3)):
            attack(u)
            if ability_ready(0) and slot_is_reset(0):
                cast_self(0)
                attack(u)
            if ability_ready(1) and slot_is_reset(1):
                cast_self(1)
                attack(u)
        if can_move() and distance(position(), unit_position(u)) > 1 and not (i_am_ranged() and distance(position(), unit_position(u)) <= 3):
            move_towards(unit_position(u))
        end_turn()
    else:
        move_away_from(unit_position(u))
        end_turn()

def go(t):
    claim(t)
    move_towards(t)
    end_turn()

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_cassi_issac()):
        pick(champ_cassi_issac())
    elif available(pool, champ_varg()):
        pick(champ_varg())
    elif available(pool, champ_willow()):
        pick(champ_willow())
    else:
        pick(random_champion(pool))
    end_turn()
else:
    keep hunter = i_am(champ_heart_of_ruin()) or i_am(champ_vendetta()) or i_am(champ_varg())
    keep guard = i_am(champ_ryth()) or i_am(champ_willow()) or i_am(champ_marcella()) or i_am(champ_tavi())
    keep home = spawn_region(ally())
    keep monoRing = ring(monolith_tiles(), 2)
    keep golemRing = ring(golem_tiles(), 1)
    if gold() >= 30 and (not alive() or contains(home, position())):
        if guard:
            buy(shard(stat_health()), floor(gold() / 30))
        else:
            buy(shard(stat_strength()), floor(gold() / 30))
    if not alive():
        end_turn()
    if channeling():
        end_turn()
    let me = position()
    let hp = health() / max_health()
    let rnd = round_number()
    # heal up on spawn
    if contains(home, me) and hp < 0.95 and enemies_within(3) == 0:
        end_turn()
    # retreat
    if hp < 0.35:
        let near = nearest(enemies_visible())
        if exists(near) and distance(me, unit_position(near)) <= 5:
            move_away_from(unit_position(near))
        else:
            recall()
        end_turn()
    # tribute
    if gems() >= 30 or (gems() > 0 and rnd > 1750) or (gems() >= 12 and hp < 0.55):
        if enemies_within(3) == 0:
            let alt = closest(minus(altars(), locked_altars()))
            if exists(alt):
                if distance(me, alt) <= 1:
                    tribute(alt)
                else:
                    move_towards(alt)
                end_turn()
    # heal allies
    if (slot_is_heal(0) and ability_ready(0)) or (slot_is_heal(1) and ability_ready(1)):
        let pal = weakest(allies_visible())
        if exists(pal) and unit_health_frac(pal) < 0.6:
            if slot_is_heal(0) and ability_ready(0):
                cast_at_unit(0, pal)
            else:
                cast_at_unit(1, pal)
    # fight enemy champions
    if enemies_within(6) > 0:
        let ls = local_strength(6)
        let tt = team_target()
        if exists(tt) and distance(me, unit_position(tt)) <= 6:
            fight(tt, ls, hunter, guard)
        else:
            let w = weakest(enemies_visible())
            if exists(w):
                fight(w, ls, hunter, guard)
    # hit camps in range
    let cu = weakest(filter(camps_visible(), in_attack_range()))
    if exists(cu) and can_attack():
        let cp = unit_position(cu)
        if not contains(monoRing, cp) and (in_danger() or (hunter and rnd > 300) or not contains(golemRing, cp)):
            if ability_ready(0) and (slot_is_damage(0) or slot_is_aoe(0)) and not slot_is_dash(0) and distance(me, cp) <= slot_range(0):
                cast_at_unit(0, cu)
            if ability_ready(1) and (slot_is_damage(1) or slot_is_aoe(1)) and not slot_is_dash(1) and distance(me, cp) <= slot_range(1):
                cast_at_unit(1, cu)
            attack(cu)
            if ability_ready(0) and slot_is_reset(0):
                cast_self(0)
                attack(cu)
            if ability_ready(1) and slot_is_reset(1):
                cast_self(1)
                attack(cu)
            end_turn()
    # capture cleared camps
    let cap = closest(capturable_spawns())
    if exists(cap) and distance(me, cap) <= 10:
        if distance(me, cap) > 0:
            move_towards(cap)
        end_turn()
    # choose a camp by role
    let claimed = claimed_by_allies()
    let resp = respawning_visible_spawns()
    if rnd < 150 and exists(closest(minus(claimed, resp))):
        let tgt = closest(minus(claimed, resp))
        go(tgt)
    elif hunter and rnd > 300:
        let tgt = closest(minus(minus(union(union(elk_tiles(), wolf_tiles()), golem_tiles()), claimed), resp))
        if exists(tgt):
            go(tgt)
    elif hunter:
        let tgt = closest(minus(minus(union(elk_tiles(), wolf_tiles()), claimed), resp))
        if exists(tgt):
            go(tgt)
    elif guard:
        let alt0 = closest(altars())
        let tgt = closest(minus(minus(filter(union(union(wolf_tiles(), gem_cluster_tiles()), gold_cluster_tiles()), within(15, alt0)), claimed), resp))
        if exists(tgt):
            go(tgt)
        if exists(alt0) and distance(me, alt0) > 2:
            move_towards(alt0)
            end_turn()
    else:
        let tgt = closest(minus(minus(union(gem_cluster_tiles(), wolf_tiles()), claimed), resp))
        if exists(tgt):
            go(tgt)
    # fallback: any non-monolith camp
    let fb = closest(minus(minus(camp_spawn_tiles(), monoRing), resp))
    if exists(fb):
        move_towards(fb)
    end_turn()

# Plan (macro route and timing):
# 1. Claim coordination: each champion claims the camp group it walks toward, and goal selection skips
#    groups that allies already claim, so the team spreads over different camps instead of stacking.
# 2. Unclaim when no goal remains, so stale claims do not block allies.
# 3. Keep the existing fight, retreat, bank and vision logic unchanged, so the macro change is isolated.
# 4. Late-game camp sweep (after round 800 with no gems banked) also respects ally claims.

# zg15: ability-aware casting. Shields/heals on self, AoE at tile, dashes kept for travel.
def cast_on(slot, u):
    if ability_ready(slot) and distance(position(), unit_position(u)) <= slot_range(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif slot_is_aoe(slot):
            cast_at_tile(slot, unit_position(u))
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
