    end_turn()

# stun opener from out of attack reach: stun before the burst, dash in if the stun is a dash
let foe = nearest( enemies_visible() )
if exists(foe) and not contains( spawn_region(enemy()), unit_position(foe) ):
    let fd = distance( position(), unit_position(foe) )
    if ability_ready(0) and slot_stun(0) > 0 and fd <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            dash_towards(0, unit_position(foe))
        else:
