    end_turn()

# late-game sweep when the team has banked nothing: skip groups allies already claim
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ), claimed_by_allies() ) ) )
    end_turn()

# goals: camp groups not being cleared by an ally, not monolith or golem groups
let goals = minus( minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups ), claimed_by_allies() )

if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# claim coordination: announce the group we walk toward, or drop a stale claim when none is left
if exists(goal):
    claim(goal)
else:
    unclaim()

if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)

# VISION: front-liners ward a bush within 2 tiles on the way to a goal, only when safe.
if (i_am(champ_heart_of_ruin()) or i_am(champ_vesper_vale())) and fuel_remaining() > 50000:
    if enemies_within(8) == 0 and not in_danger():
        let ward_bush = first( filter( bushes(), within(2, position()) ) )
        if exists(ward_bush):
            place_ward(ward_bush)

move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# PLAN (combat micro first, farming second):
# - Draft: take champions with stuns/burst first (Ryth, Heart of Ruin, Vendetta, Varg, Cassi), else random.
# - Every turn, one champion thinks:
#   1. Dead: buy Strength shards. Channeling: do nothing.
#   2. On spawn: buy shards, and stay to heal unless an enemy is close.
#   3. Enemy visible: read local_strength.
#      Losing or low HP and close: stun the chaser, finish a near-dead target if one is in range, then step away.
#      Winning, or enemy adjacent: fight. Open with the stun, then damage abilities.
#      Focus the team target if it is close. Otherwise take the weakest enemy in range and name it the team target.
#      Melee closes with a dash and hits on the same turn.
#      Ranged kites by stepping off when a melee is on top of it at low HP. Use attack resets.
#   4. Carrying enough gems (or late game, or the gems would win): walk to the altar and tribute.
#   5. Low HP and no enemy: recall.
#   6. Farm: stand on capturable camps. Hit the weakest camp in range, but never monoliths, and golems only once strong.
#      Otherwise claim and walk to the nearest unclaimed, non-respawning wolf/elk/gem/gold camp.

def fight(t, me, rng, hpf):
  if ability_ready(0) and slot_stun(0) > 0 and distance(me, unit_position(t)) <= slot_range(0):
    cast_at_unit(0, t)
  if ability_ready(1) and slot_stun(1) > 0 and distance(me, unit_position(t)) <= slot_range(1):
    cast_at_unit(1, t)
  if ability_ready(0) and (slot_is_damage(0) or slot_is_aoe(0)) and distance(me, unit_position(t)) <= slot_range(0):
    cast_at_unit(0, t)
  if ability_ready(1) and (slot_is_damage(1) or slot_is_aoe(1)) and distance(me, unit_position(t)) <= slot_range(1):
    cast_at_unit(1, t)
  if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)) and hpf < 0.7:
    cast_self(0)
  if ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)) and hpf < 0.7:
    cast_self(1)
  if distance(me, unit_position(t)) <= rng:
    if i_am_ranged() and distance(me, unit_position(t)) <= 1 and hpf < 0.6:
      move_away_from(unit_position(t))
    else:
      attack(t)
      if slot_is_reset(0) and ability_ready(0):
        cast_self(0)
        attack(t)
      if slot_is_reset(1) and ability_ready(1):
        cast_self(1)
        attack(t)
  else:
    if (not i_am_ranged()) and slot_is_dash(0) and ability_ready(0):
      dash_towards(0, unit_position(t))
    elif (not i_am_ranged()) and slot_is_dash(1) and ability_ready(1):
      dash_towards(1, unit_position(t))
    if can_move():
      move_towards(unit_position(t))
    if can_attack() and distance(position(), unit_position(t)) <= rng:
      attack(t)

