# zg15: ability-aware casting. Shields/heals on self, AoE at tile, dashes kept for travel.
def cast_on(slot, u):
    if ability_ready(slot) and distance(position(), unit_position(u)) <= slot_range(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif slot_is_aoe(slot):
            cast_at_tile(slot, unit_position(u))
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

