if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    # attack reset on camps too (tune line): a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# rally: a healthy champion with no fight in reach joins the team's focus target when a fight was
# called recently (byte 7 = round/8 written by whoever engaged; fresh within ~3 windows)
if health() > 0.6 * max_health() and read_shared(7) >= floor( round_number() / 8 ) - 3 and exists(team_target()):
    if not contains( spawn_region(enemy()), unit_position(team_target()) ):
        move_towards( unit_position(team_target()) )
        end_turn()

# nothing tributed by round 300 (00contest: only monoliths carry gems): go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()

# monolith commit (late game, team macro): after round 1000 a healthy champion joins a monolith that an
# ally already claims (2+ attackers); after round 1200 the first healthy champion claims the closest one.
# Not in_danger here: the retreat block above has already handled threatened champions.
if round_number() > 1000 and health() > 0.7 * max_health():
    let mono_goal = closest( monolith_tiles() )
    if exists(mono_goal):
        if claim_count(mono_goal) >= 1:
            move_towards(mono_goal)
            end_turn()
        if round_number() > 1200 and claim_count(mono_goal) == 0:
            claim(mono_goal)
            move_towards(mono_goal)
            end_turn()

let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
